// GET /api/tasks?limit=25  -> recent tasks for dashboard widget
apiTasksRouter.get("/", async (req, res) => {
  console.log("[phase57c-router] /api/tasks probe", {
    originalUrl: req.originalUrl,
    baseUrl: req.baseUrl,
    path: req.path,
    referer: req.get("referer") || null,
    userAgent: req.get("user-agent") || null,
    accept: req.get("accept") || null,
  });

  try {
    const pool = _getPoolOrFail(res);
    if (!pool) return;

    const limit = Math.max(1, Math.min(200, Number(req.query?.limit ?? 25) || 25));
    const r = await pool.query(
      `
      SELECT
        t.id,
        t.task_id,
        t.title,
        t.status,
        t.claimed_by,
        t.updated_at,
        completed.payload->>'outcome_preview' AS outcome_preview,
        completed.payload->>'explanation_preview' AS explanation_preview,
        completed.payload->'artifact' AS artifact,
        completed.payload->'artifacts' AS artifacts,
        completed.payload AS guidance
      FROM tasks t
      LEFT JOIN LATERAL (
        SELECT te.payload
        FROM task_events te
        WHERE te.task_id = t.task_id
          AND te.kind = 'task.completed'
        ORDER BY te.id DESC
        LIMIT 1
      ) completed ON true
      ORDER BY t.updated_at DESC NULLS LAST, t.id DESC
      LIMIT $1
      `,
      [limit]
    );

    res.status(200).json({ ok: true, tasks: r.rows || [] });
  } catch (e) {
    console.error("[phase25] /api/tasks list error", e);
    res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});



// GET /api/tasks/:task_id/artifact-preview

apiTasksRouter.get("/:task_id/artifact-preview", async (req, res) => {

  try {

    const taskId = String(req.params.task_id || "").trim();

    if (!taskId) {

      return res.status(400).json({ ok: false, error: "task_id_required" });

    }

    const q = await globalThis.__DB_POOL.query(

      `

      SELECT

        completed.payload->'artifact' AS artifact,

        completed.payload->'artifacts' AS artifacts

      FROM tasks t

      LEFT JOIN LATERAL (

        SELECT te.payload

        FROM task_events te

        WHERE te.task_id = t.task_id

          AND te.kind = 'task.completed'

        ORDER BY te.ts DESC

        LIMIT 1

      ) completed ON true

      WHERE t.task_id = $1

      LIMIT 1

      `,

      [taskId]

    );

    const row = q.rows?.[0] || null;

    if (!row) {

      return res.status(404).json({ ok: false, error: "task_not_found" });

    }

    const artifact =

      row.artifact ||

      (Array.isArray(row.artifacts) ? row.artifacts[0] : null);

    if (!artifact || !artifact.path) {

      return res.status(404).json({ ok: false, error: "artifact_not_found" });

    }

    const artifactDir = process.env.MB_ARTIFACT_DIR || "/app/data/artifacts";

    const resolvedPath = path.resolve(String(artifact.path));

    const resolvedDir = path.resolve(artifactDir);

    if (!resolvedPath.startsWith(resolvedDir)) {

      return res.status(403).json({ ok: false, error: "artifact_path_rejected" });

    }

    if (!fs.existsSync(resolvedPath)) {

      return res.status(404).json({ ok: false, error: "artifact_file_missing" });

    }

    const content = fs.readFileSync(resolvedPath, "utf8");

    return res.status(200).json({

      ok: true,

      task_id: taskId,

      artifact: {

        filename: artifact.filename || null,

        type: artifact.type || null,

        size_bytes: artifact.size_bytes || null,

        created_at: artifact.created_at || null

      },

      content

    });

  } catch (e) {

    console.error("[phase719] artifact preview route error", e);

    return res.status(500).json({ ok: false, error: "artifact_preview_failed" });

  }

});


